syntax = "proto3";

package vector;

// A single record to be ingested into the vector store.
message VectorRecord {
  int64 id       = 1;
  repeated float vector   = 2;
  string metadata = 3;
}

// Summary returned after a completed ingestion stream.
message IngestSummary {
  int64 received = 1;  // total records received from the client stream
  int64 written  = 2;  // rows actually written to LanceDB
  int64 batches  = 3;  // number of batch flushes performed
}

// A nearest-neighbor search request.
message SearchRequest {
  repeated float query_vector = 1;
  int32 k                     = 2;
}

// A single result record returned by Search.
message SearchResult {
  int64  id       = 1;
  float  distance = 2;
  string metadata = 3;
}

// The search response containing an ordered list of nearest neighbors.
message SearchResponse {
  repeated SearchResult results = 1;
}

service VectorService {
  // Client-streaming RPC: client pushes many VectorRecord messages,
  // server batches them and writes to LanceDB, then returns a summary.
  rpc IngestVectors(stream VectorRecord) returns (IngestSummary);

  // Unary RPC: nearest-neighbor search against all stored vectors.
  rpc Search(SearchRequest) returns (SearchResponse);
}
